INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.settings.users.create.sendInvitationTooltip', 'pt-PT', 'Quando ativado, será enviado um email de convite ao utilizador. Este definirá a sua própria palavra-passe através de uma página de boas-vindas segura. O campo de palavra-passe acima passa a ser opcional — se deixado vazio, é definido um marcador de posição aleatório no fornecedor de identidade e o utilizador define-o no primeiro acesso.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
