INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin', 'pt-PT', 'O indicador de administrador de identidade permite que o utilizador aceda ao sistema IDP para fazer alterações de nível administrativo, mas não concede direitos de administração a esta aplicação. Para conceder acessos de administração à aplicação, defina os papéis aplicativos.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
