INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified', 'pt-PT', 'Indica se o processo de verificação da identidade foi concluído com sucesso. Pode depender de um processo KYC ou de outro tipo de verificação.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
