INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.email_verified', 'pt-PT', 'Indica se o email foi verificado, geralmente através de um link enviado para a caixa de entrada que se presume ser legível apenas pelo utilizador cujo perfil estamos a configurar.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
